int calls = 0;
int v = Solution.ReadWithRetry(() => { calls++; return calls >= 3 ? 42 : throw new InvalidOperationException("flaky"); }, 5);
Cj.Eq(v, 42, "succeeded on attempt 3");
Cj.Eq(calls, 3, "three attempts made");

int calls = 0;
bool t = false;
try { Solution.ReadWithRetry(() => { calls++; throw new InvalidOperationException("always"); }, 3); } catch (InvalidOperationException) { t = true; }
Cj.True(t, "exhaustion throws");
Cj.Eq(calls, 3, "exactly the attempt budget used");
bool t2 = false;
bool called = false;
try { Solution.ReadWithRetry(() => { called = true; return 1; }, 0); } catch (ArgumentException) { t2 = true; }
Cj.True(t2 && !called, "zero attempts rejected before any call");
